/// <param name = "_dirProduktGroup">_dirProduktGroup</param>
/// <param name = "_name1">_name1</param>
/// <returns>Name</returns>
edit Name  editDirGroupParty1(boolean  _set, KCS_DirProductGroup           _dirProduktGroup,   Name      _name1)
{
    Name                    dirPartyName1;
    DirPartyTable           dirPartyTableLookup;
    FormRun                 formRun = this.formRun();
    FormDataSource          dirPartyTableDS = formRun.dataSource('DirPartyTable');
    DirPartyTable           dirPartyTable;

    if(dirPartyTableDS)
    {
        dirPartyTable = dirPartyTableDS.cursor();
    }


    if(formHasMethod(formRun,'parmDirGroupPartyTable'))
    {
        dirPartyTableLookup = formRun.parmDirGroupPartyTable();
    }

    dirPartyName1 = _dirProduktGroup.editPartyCompetitor(_set,
                                        dirPartyTableLookup.RecId,
                                        KCS_DirProductGrpAddressRanking::one,
                                        _dirProduktGroup.KCS_DirProductGroupId,
                                        dirPartyTable) ;

    return dirPartyName1;
}

